mapper.select:
select access_log_seq as accessLogSeq, adm_seq as adminSeq, login_id as loginId, path as requestUri, '' as method, '' as remoteAddr, '' as userAgent, access_dtm as accessAt from co_adm_access_log_mst where access_dtm >= #{startDate} and access_dtm < date_add(#{endDate}, interval 1 day)
and (login_id like concat('%', #{keyword}, '%') or path like concat('%', #{keyword}, '%') or location_nm like concat('%', #{keyword}, '%'))
order by access_dtm desc limit #{limit} offset #{offset}
